contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to attempt deposit (in wei)
    function run(uint depositAmt) public payable {
        require(address(this).balance >= depositAmt, "not enough balance to forward");

        // record before-values observable from c
        uint beforeBalanceOfCaller = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;
        uint minDep = c.MinDeposit();

        bool reverted = false;
        // perform the deposit attempt sending depositAmt wei
        // call must be top-level
        try c.Deposit{value: depositAmt}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterBalanceOfCaller = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule (single assert):
        // If depositAmt >= minDep and call did not revert then caller's recorded balance increases by depositAmt
        // and contract's balance increases by depositAmt. Otherwise (depositAmt < minDep or reverted) no change.
        assert(
            (
                (depositAmt >= minDep && reverted == false) 
                && (afterBalanceOfCaller == beforeBalanceOfCaller + depositAmt) 
                && (afterContractBalance == beforeContractBalance + depositAmt)
            )
            ||
            (
                (depositAmt < minDep || reverted == true)
                && (afterBalanceOfCaller == beforeBalanceOfCaller)
                && (afterContractBalance == beforeContractBalance)
            )
        );
    }

    // allow receiving refunds if needed
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: initial deposit to ensure there is some balance, and amount to cash out
    function run(uint initialDeposit, uint cashOutAmt) public payable {
        // ensure this test contract can send initialDeposit to c
        require(address(this).balance >= initialDeposit, "insufficient funds to seed");

        // seed the contract with an initial deposit if it meets MinDeposit
        uint minDep = c.MinDeposit();
        // record before-values
        uint beforeCallerBalance = c.balances(address(this));
        uint beforeContractBalance = address(c).balance;

        bool depositReverted = false;
        if (initialDeposit > 0) {
            // try depositing; must be top-level call
            try c.Deposit{value: initialDeposit}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        // read balances after optional deposit
        uint midCallerBalance = c.balances(address(this));
        uint midContractBalance = address(c).balance;

        // Now attempt CashOut of cashOutAmt and observe whether it reverts
        bool cashoutReverted = false;
        try c.CashOut(cashOutAmt) {
            cashoutReverted = false;
        } catch {
            cashoutReverted = true;
        }

        // read after-values
        uint afterCallerBalance = c.balances(address(this));
        uint afterContractBalance = address(c).balance;

        // General rule (single assert):
        // If CashOut did NOT revert and cashOutAmt <= midCallerBalance then
        //   afterCallerBalance == midCallerBalance - cashOutAmt
        //   and afterContractBalance == midContractBalance - cashOutAmt
        // Otherwise (if reverted OR cashOutAmt > midCallerBalance) there is no change to balances
        assert(
            (
                (cashoutReverted == false && cashOutAmt <= midCallerBalance)
                && afterCallerBalance == (midCallerBalance - cashOutAmt)
                && afterContractBalance == (midContractBalance - cashOutAmt)
            )
            ||
            (
                (cashoutReverted == true || cashOutAmt > midCallerBalance)
                && afterCallerBalance == midCallerBalance
                && afterContractBalance == midContractBalance
            )
        );
    }

    // allow receiving Ether from c when CashOut succeeds
    receive() external payable { }
}

