    function run(uint64 _dep, uint64 _am) public payable {
        // We will treat _dep and _am as wei amounts (uint64 to keep parameters small but general).
        // Ensure this contract has enough balance to send deposit if requested.
        uint dep = uint(_dep);
        uint am = uint(_am);

