    constructor(C _c) { c = _c; }

    // single public entry exercising Deposit and CashOut with arbitrary amounts and origin
    function run(address depositor, uint depositAmt, uint cashOutAmt) public payable {
        require(depositor != address(0));
        // ensure this contract has enough balance to forward depositAmt
        if (depositAmt > 0) {
            require(address(this).balance >= depositAmt);
            // call Deposit from this contract but we want depositor as msg.sender — deployer runs as InvMutTest, so emulate by first
            // sending Ether to c via Deposit from this contract, then treat balances(depositor) remain unchanged.
            // To observe behaviour for the caller (InvMutTest), use this contract as the actor.
        }

        // We will act as the depositor by using this contract as msg.sender for calls on c.
        // First, record before-values for this contract's address
        uint beforeBal = c.balances(address(this));
        uint cBefore = address(c).balance;

        // If depositAmt meets MinDeposit then Deposit will increase balances; call it
        if (depositAmt > 0) {
            // call Deposit forwarding depositAmt wei
            c.Deposit{value: depositAmt}();
        }

        uint afterDepositBal = c.balances(address(this));
        uint cAfterDeposit = address(c).balance;

        // Now attempt CashOut of cashOutAmt and catch whether it reverted
        bool reverted;
        // CashOut must be a top-level state-changing call; use try/catch on external call to detect revert
        try c.CashOut(cashOutAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint finalBal = c.balances(address(this));
        uint cFinal = address(c).balance;

        // General rule: If CashOut did not revert then the contract's recorded balance for this actor decreased by exactly cashOutAmt
        // and the contract's Ether balance decreased by exactly cashOutAmt. If it reverted then balances are unchanged from before the call.
        assert(
            (!reverted && finalBal + cashOutAmt == afterDepositBal && cAfterDeposit >= cashOutAmt && cFinal + cashOutAmt == cAfterDeposit)
            || (reverted && finalBal == afterDepositBal && cFinal == cAfterDeposit)
        );
    }

    receive() external payable {}
}

